      "\u0391\u03BD \u03B5\u03C0\u03B9\u03B4\u03B5\u03B9\u03BD\u03BF\u03CD\u03BC\u03B5\u03BD\u03B7 \u03B1\u03C0\u03CC\u03C6\u03C1\u03B1\u03BE\u03B7: \u03AC\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C4\u03C1\u03B1\u03CD\u03BC\u03B1\u03C4\u03BF\u03C2 \u03A3\u03A4\u039F \u039A\u03A1\u0395\u0392\u0391\u03A4\u0399 \u03B1\u03BC\u03AD\u03C3\u03C9\u03C2",
